style.css:
@-moz-document domain("roblox.com") {
/* =========================================================
   ROBLOX V3 — FORCE WALLPAPER / GOLD LUXURY
   ========================================================= */

:root{
  --wallpaper: url("https://i.pinimg.com/1200x/7c/87/e8/7c87e8512f44f7ffd0eccadfd9903f60.jpg");

  --gold: #f6c76e;
  --gold2: #ffd998;
  --gold3: #e0ae59;
  --champagne: #fff4de;
  --text: #f7e8c4;
  --muted: #d9c39a;

  --glass0: rgba(0,0,0,.08);
  --glass1: rgba(8,8,12,.18);
  --glass2: rgba(10,10,14,.28);
  --glass3: rgba(10,10,14,.42);
  --glass4: rgba(10,10,14,.62);

  --border: rgba(255,217,152,.16);
  --border2: rgba(255,217,152,.28);

  --radius-xl: 24px;
  --radius-lg: 18px;
  --radius-md: 14px;
  --radius-sm: 10px;

  --shadow: 0 18px 42px rgba(0,0,0,.28);
  --tr: .28s ease;
}

/* =========================================================
   1) FOND GLOBAL VRAIMENT FORCÉ
   ========================================================= */

html{
  background: #000 !important;
  background-image:
    linear-gradient(135deg, rgba(0,0,0,.22), rgba(0,0,0,.12)),
    radial-gradient(circle at 80% 20%, rgba(255,190,90,.10), transparent 24%),
    radial-gradient(circle at 18% 28%, rgba(246,199,110,.08), transparent 26%),
    url("https://i.pinimg.com/1200x/7c/87/e8/7c87e8512f44f7ffd0eccadfd9903f60.jpg") !important;
  background-size: cover !important;
  background-position: center center !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

body{
  background: transparent !important;
  background-color: transparent !important;
  color: var(--text) !important;
}

/* gros calque visuel directement sur body */
body::before{
  content:"";
  position: fixed;
  inset: 0;
  z-index: -999999 !important;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(0,0,0,.03), rgba(0,0,0,.10)),
    linear-gradient(120deg, rgba(255,217,152,.025), transparent 35%, transparent 70%, rgba(224,174,89,.02)),
    var(--wallpaper) center / cover no-repeat;
  filter: blur(2.5px) brightness(.86) saturate(1.05);
  transform: scale(1.02);
}

/* =========================================================
   2) LES WRAPPERS PRINCIPAUX ROBLOX REÇOIVENT LE FOND AUSSI
   (c'est ça qui doit débloquer le "fond invisible")
   ========================================================= */

#rbx-body,
#container-main,
main,
[role="main"],
.content,
.content-container,
.page-content,
.game-home-page-container,
.home-page-container,
.home-container,
.games-page-container,
.discovery-container,
.rbx-body,
.rbx-page,
.rbx-content,
.main-content,
.main-container,
.content-wrapper,
.content-body,
.app-shell,
.universal-app-container,
#navigation + div,
#navigation ~ div,
body > div,
body > div > div,
body > div > div > div {
  background-color: transparent !important;
}

/* on pose AUSSI le wallpaper sur les plus gros conteneurs */
#rbx-body,
#container-main,
main,
[role="main"],
.content,
.page-content,
.home-page-container,
.home-container,
.main-content,
.main-container,
.content-wrapper {
  background-image:
    linear-gradient(135deg, rgba(0,0,0,.10), rgba(0,0,0,.06)),
    url("https://i.pinimg.com/1200x/7c/87/e8/7c87e8512f44f7ffd0eccadfd9903f60.jpg") !important;
  background-size: cover !important;
  background-position: center center !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

/* =========================================================
   3) ON TUE LES FONDS GRIS / BLANCS ROBLOX
   ========================================================= */

/* brute force sur presque tous les conteneurs courants */
div,
section,
main,
article,
aside,
header,
footer,
ul,
li{
  background-color: transparent;
}

/* sauf éléments interactifs qu’on va restyler plus bas */
nav,
button,
input,
textarea,
img,
video{
  background-color: initial;
}

/* wrappers Roblox fréquents */
[class*="container"],
[class*="Container"],
[class*="wrapper"],
[class*="Wrapper"],
[class*="content"],
[class*="Content"],
[class*="page"],
[class*="Page"],
[class*="section"],
[class*="Section"],
[class*="stack"],
[class*="Stack"],
[class*="grid"],
[class*="Grid"],
[class*="list"],
[class*="List"]{
  background-color: transparent !important;
  box-shadow: none !important;
}

/* si Roblox injecte des backgrounds inline */
[style*="background-color"],
[style*="background: rgb"],
[style*="background:#"],
[style*="background: #"]{
  background-color: transparent !important;
}

/* =========================================================
   4) NAVBAR
   ========================================================= */

#navigation,
.navbar,
.navbar-fixed-top,
.rbx-navbar,
.topbar,
.header{
  background: rgba(8,8,12,.44) !important;
  backdrop-filter: blur(14px) !important;
  -webkit-backdrop-filter: blur(14px) !important;
  border-bottom: 1px solid var(--border) !important;
  box-shadow: 0 10px 28px rgba(0,0,0,.18) !important;
}

#navigation a,
.navbar a,
.rbx-navbar a,
.topbar a,
.header a{
  color: var(--gold2) !important;
  transition: var(--tr) !important;
}

#navigation a:hover,
.navbar a:hover,
.rbx-navbar a:hover,
.topbar a:hover,
.header a:hover{
  color: var(--champagne) !important;
  text-shadow: 0 0 10px rgba(255,217,152,.18);
}

/* =========================================================
   5) BLOCS PRINCIPAUX / PANELS
   ========================================================= */

.section,
.section-content,
.content-box,
.content-card,
.game-home-page-container,
.home-page-container,
.discovery-container,
.games-list-container,
.profile-container,
.friends-list,
.card,
.panel,
.content-body,
.content-wrapper,
[class*="card"],
[class*="Card"],
[class*="panel"],
[class*="Panel"],
[class*="tile"],
[class*="Tile"]{
  background: var(--glass1) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border: 1px solid rgba(255,217,152,.10) !important;
  border-radius: 20px !important;
  box-shadow: 0 14px 34px rgba(0,0,0,.18) !important;
}

/* =========================================================
   6) CARTES DE JEUX
   ========================================================= */

.game-card,
.game-tile,
.game-container,
.game-item,
.card-item,
.item-card,
.list-item,
.avatar-card,
.friend-tile,
.game-grid > li,
.games-list > li{
  background: linear-gradient(180deg, rgba(12,12,18,.46), rgba(8,8,12,.62)) !important;
  border: 1px solid rgba(255,217,152,.12) !important;
  border-radius: 20px !important;
  overflow: hidden !important;
  box-shadow: var(--shadow) !important;
  transition: transform var(--tr), box-shadow var(--tr), border-color var(--tr) !important;
}

.game-card:hover,
.game-tile:hover,
.game-container:hover,
.game-item:hover,
.card-item:hover,
.item-card:hover,
.list-item:hover,
.avatar-card:hover,
.friend-tile:hover,
.game-grid > li:hover,
.games-list > li:hover{
  transform: translateY(-6px) !important;
  border-color: rgba(255,217,152,.24) !important;
  box-shadow:
    0 20px 40px rgba(0,0,0,.28),
    0 0 18px rgba(255,217,152,.06) !important;
}

.game-card img,
.game-tile img,
.game-container img,
.game-item img,
.card-item img,
.item-card img,
.avatar-card img,
.friend-tile img{
  border-radius: 16px !important;
  transition: transform .35s ease, filter .35s ease !important;
  filter: saturate(1.08) brightness(1.02) contrast(1.03) !important;
}

.game-card:hover img,
.game-tile:hover img,
.game-container:hover img,
.game-item:hover img,
.card-item:hover img,
.item-card:hover img,
.avatar-card:hover img,
.friend-tile:hover img{
  transform: scale(1.04) !important;
}

/* overlay premium */
.game-card .thumbnail,
.game-tile .thumbnail,
.game-container .thumbnail,
.item-card .thumbnail,
.avatar-card .thumbnail,
.friend-tile .thumbnail,
[class*="thumbnail"]{
  position: relative !important;
  overflow: hidden !important;
  border-radius: 16px !important;
}

.game-card .thumbnail::before,
.game-tile .thumbnail::before,
.game-container .thumbnail::before,
.item-card .thumbnail::before,
.avatar-card .thumbnail::before,
.friend-tile .thumbnail::before,
[class*="thumbnail"]::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:2;
  pointer-events:none;
  background:
    linear-gradient(180deg, rgba(255,255,255,.03), transparent 30%, transparent 60%, rgba(0,0,0,.16)),
    linear-gradient(135deg, rgba(255,217,152,.08), transparent 38%, transparent 72%, rgba(224,174,89,.06));
}

/* =========================================================
   7) TEXTES EN OR / CHAMPAGNE
   ========================================================= */

body,
p,
span,
li,
small,
label{
  color: #efdcb4 !important;
}

h1,h2,h3,h4,h5,
.section-title,
.container-header,
.font-header-1,
.font-header-2,
.font-caption-header,
.game-card-name,
.game-name,
.title{
  color: var(--gold2) !important;
  text-shadow: 0 2px 10px rgba(0,0,0,.18) !important;
}

.text-secondary,
.text-label,
.text-description,
.text-overflow,
.game-card-info,
.game-card-reason,
.game-card-votes,
.game-card-player-count{
  color: var(--muted) !important;
}

a{
  color: var(--gold) !important;
}
a:hover{
  color: var(--champagne) !important;
}

/* =========================================================
   8) BOUTONS / INPUTS
   ========================================================= */

button,
.btn,
.btn-primary,
.btn-secondary,
.btn-control-sm,
.btn-growth-md,
.btn-full-width{
  background: linear-gradient(135deg, rgba(246,199,110,.16), rgba(224,174,89,.10)) !important;
  color: #fff5df !important;
  border: 1px solid rgba(255,217,152,.18) !important;
  border-radius: 999px !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.14) !important;
}

button:hover,
.btn:hover,
.btn-primary:hover,
.btn-secondary:hover,
.btn-control-sm:hover,
.btn-growth-md:hover,
.btn-full-width:hover{
  border-color: rgba(255,217,152,.28) !important;
  box-shadow:
    0 12px 28px rgba(0,0,0,.18),
    0 0 14px rgba(255,217,152,.06) !important;
}

input,
input[type="text"],
input[type="search"],
.form-control{
  background: rgba(10,10,14,.34) !important;
  color: var(--champagne) !important;
  border: 1px solid rgba(255,217,152,.14) !important;
  border-radius: 999px !important;
}

/* =========================================================
   9) SCROLLBAR
   ========================================================= */

::-webkit-scrollbar{ width: 10px !important; height: 10px !important; }
::-webkit-scrollbar-track{ background: rgba(0,0,0,.16) !important; }
::-webkit-scrollbar-thumb{
  background: linear-gradient(180deg, rgba(246,199,110,.74), rgba(224,174,89,.70)) !important;
  border-radius: 999px !important;
  border: 2px solid rgba(10,10,10,.24) !important;
}

/* =========================================================
   10) PETIT ZOOM OUT POUR VOIR PLUS LE WALLPAPER
   ========================================================= */

main,
[role="main"],
.content,
.page-content,
.home-page-container{
  zoom: .95;
}
}
